/* ═══════ HOOKS ═══════ */
function useReveal(threshold = 0.12) {
  const ref = useRef(null);
  const [vis, setVis] = useState(false);
  useEffect(() => {
    const el = ref.current; if (!el) return;
    const obs = new IntersectionObserver(([e]) => { if (e.isIntersecting) { setVis(true); obs.disconnect(); } }, { threshold });
    obs.observe(el); return () => obs.disconnect();
  }, [threshold]);
  return [ref, vis];
}

/* ═══════ SIMPLE COMPONENTS ═══════ */
function Reveal({ children, delay = 0, style = {} }) {
  const [ref, vis] = useReveal();
  return <div ref={ref} style={{ ...style, opacity: vis ? 1 : 0, transform: vis ? "translateY(0)" : "translateY(36px)", transition: `all 1s cubic-bezier(.22,1,.36,1) ${delay}s` }}>{children}</div>;
}
function MaskReveal({ children, delay = 0 }) {
  const [ref, vis] = useReveal(0.15);
  return <div ref={ref} style={{ overflow: "hidden" }}><div style={{ transform: vis ? "translateY(0)" : "translateY(100%)", opacity: vis ? 1 : 0, transition: `all .9s cubic-bezier(.22,1,.36,1) ${delay}s` }}>{children}</div></div>;
}
function AnimLine({ width = "80px", delay = 0, color = C.orange }) {
  const [ref, vis] = useReveal();
  return <div ref={ref} style={{ height: 1, background: color, width: vis ? width : 0, transition: `width 1.2s cubic-bezier(.22,1,.36,1) ${delay}s` }} />;
}
function SectionLabel({ en, jp, align = "left", light = false }) {
  return (
    <div style={{ textAlign: align, marginBottom: 48 }}>
      <MaskReveal><div style={{ fontFamily: F.en, fontWeight: 300, fontSize: "clamp(11px,1.4vw,13px)", letterSpacing: 6, color: C.orange, textTransform: "uppercase", marginBottom: 8 }}>{en}</div></MaskReveal>
      {jp && <MaskReveal delay={0.08}><h2 style={{ fontFamily: F.jp, fontWeight: 300, fontSize: "clamp(22px,3.2vw,36px)", lineHeight: 1.8, letterSpacing: "0.06em", color: light ? "#E8E4DF" : C.text }}>{jp}</h2></MaskReveal>}
    </div>
  );
}

/* ═══════ CANVAS DISSOLVE HELPER ═══════ */
function drawImageCover(ctx, img, cw, ch, dpr = 1) {
  const w = cw * dpr, h = ch * dpr;
  const ir = img.naturalWidth / img.naturalHeight;
  const cr = w / h;
  let sx, sy, sw, sh;
  if (ir > cr) { sh = img.naturalHeight; sw = sh * cr; sx = (img.naturalWidth - sw) / 2; sy = 0; }
  else { sw = img.naturalWidth; sh = sw / cr; sx = 0; sy = (img.naturalHeight - sh) / 2; }
  ctx.drawImage(img, sx, sy, sw, sh, 0, 0, w, h);
}

/* Draw image with vertical pan: panProgress 0=top, 1=bottom */
function drawImagePan(ctx, img, cw, ch, dpr = 1, panProgress = 0) {
  const w = cw * dpr, h = ch * dpr;
  const ir = img.naturalWidth / img.naturalHeight;
  const cr = w / h;
  if (ir >= cr) {
    /* Landscape image — just cover */
    drawImageCover(ctx, img, cw, ch, dpr);
    return;
  }
  /* Portrait image — fit width, pan vertically */
  const sw = img.naturalWidth;
  const sh = sw / cr; /* visible height in source coords */
  const maxSy = img.naturalHeight - sh;
  const sy = maxSy * panProgress;
  ctx.drawImage(img, 0, sy, sw, sh, 0, 0, w, h);
}

function startDissolve(canvas, nextImg, dissolveRef, duration = 1200) {
  if (!canvas || !nextImg) return;
  if (dissolveRef.current.animId) cancelAnimationFrame(dissolveRef.current.animId);
  const ctx = canvas.getContext("2d");
  const dpr = window.devicePixelRatio || 1;
  const w = canvas.width, h = canvas.height;
  const cw = canvas.offsetWidth, ch = canvas.offsetHeight;

  /* Capture current (old) image */
  const oldCanvas = document.createElement("canvas");
  oldCanvas.width = w; oldCanvas.height = h;
  oldCanvas.getContext("2d").drawImage(canvas, 0, 0);

  /* Draw next image to offscreen canvas */
  const nextCanvas = document.createElement("canvas");
  nextCanvas.width = w; nextCanvas.height = h;
  drawImageCover(nextCanvas.getContext("2d"), nextImg, cw, ch, dpr);

  const t0 = performance.now();
  function frame(now) {
    const p = Math.min((now - t0) / duration, 1);
    /* Smooth ease-in-out */
    const ease = p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;

    /* Draw old image, then blend new image on top */
    ctx.globalAlpha = 1;
    ctx.drawImage(oldCanvas, 0, 0);
    ctx.globalAlpha = ease;
    ctx.drawImage(nextCanvas, 0, 0);
    ctx.globalAlpha = 1;

    if (p < 1) {
      dissolveRef.current.animId = requestAnimationFrame(frame);
    } else {
      ctx.drawImage(nextCanvas, 0, 0);
      dissolveRef.current.animId = null;
    }
  }
  dissolveRef.current.animId = requestAnimationFrame(frame);
}

