/* ═══════ HELPER ═══════ */
function isLight(hex) {
  if (!hex) return true;
  const c = hex.replace("#", "");
  const r = parseInt(c.substr(0,2),16), g = parseInt(c.substr(2,2),16), b = parseInt(c.substr(4,2),16);
  return (r * 299 + g * 587 + b * 114) / 1000 > 128;
}

/* ═══════ FULLSCREEN MENU ═══════ */
function FullMenu({ open, onClose, scrollTo }) {
  const links = [["Works","works"],["About","about"],["Statement","statement"],["Process","process"],["Contact","contact"]];
  return (
    <div style={{ position: "fixed", inset: 0, zIndex: 200, background: "rgba(255,255,255,.97)", backdropFilter: "blur(20px)", opacity: open?1:0, pointerEvents: open?"auto":"none", transition: "opacity .4s", display: "flex", flexDirection: "column", justifyContent: "center", alignItems: "center" }}>
      <button onClick={onClose} style={{ position: "absolute", top: 24, right: 40, background: "none", border: "none", cursor: "pointer", fontSize: 28, color: C.sub, fontFamily: F.sans }}>✕</button>
      <nav style={{ display: "flex", flexDirection: "column", gap: 4, alignItems: "center" }}>
        {links.map(([l,id],i) => (
          <button key={id} onClick={() => { scrollTo(id); onClose(); }} style={{ background: "none", border: "none", cursor: "pointer", fontFamily: F.en, fontSize: "clamp(28px,5vw,48px)", fontWeight: 300, color: C.text, letterSpacing: "0.06em", padding: "8px 16px", opacity: open?1:0, transform: open?"translateY(0)":"translateY(16px)", transition: `all .5s ease ${.1+i*.05}s` }}
          onMouseEnter={e=>e.target.style.color=C.orange} onMouseLeave={e=>e.target.style.color=C.text}>{l}</button>
        ))}
      </nav>
    </div>
  );
}

